BEGIN TRANSACTION;
CREATE TABLE collections (
    id        INTEGER PRIMARY KEY,
    name      TEXT NOT NULL UNIQUE,
    specialty TEXT NOT NULL,
    root      TEXT NOT NULL
);
CREATE TABLE files (
    id          INTEGER PRIMARY KEY,
    collection  TEXT NOT NULL,
    path        TEXT NOT NULL UNIQUE,
    size        INTEGER NOT NULL,
    modified    REAL NOT NULL,
    fingerprint TEXT NOT NULL
, title TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', use_when TEXT NOT NULL DEFAULT '', date TEXT NOT NULL DEFAULT '', missing INTEGER NOT NULL DEFAULT 0);
CREATE TABLE labels (
    id      INTEGER PRIMARY KEY,
    file    INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,
    name    TEXT NOT NULL,
    value   TEXT NOT NULL,
    made_by TEXT NOT NULL CHECK (made_by IN ('hand', 'rule', 'ai')),
    UNIQUE (file, name, value, made_by)
);
CREATE TABLE rules (
    id      INTEGER PRIMARY KEY,
    reads   TEXT NOT NULL CHECK (reads IN ('name', 'location', 'content')),
    pattern TEXT NOT NULL,
    name    TEXT NOT NULL,
    value   TEXT NOT NULL
);
CREATE TABLE sources (
    id        INTEGER PRIMARY KEY,
    file      INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,
    author    TEXT NOT NULL,
    came_from TEXT NOT NULL,
    date      TEXT
);
COMMIT;
